/**
 * Embed the built console (console/dist, `vite build`) into the server as
 * src/dashboard/assets.generated.ts, so `bun build --compile` binaries and
 * the Docker image serve it without any file on disk.
 *
 *   bun run console:build   # vite build + this script
 *
 * The generated file is committed; CI rebuilds it and fails when it differs
 * (the console source and the embedded copy can never drift apart).
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { extname, join, relative } from "node:path";

const root = join(import.meta.dir, "..");
const dist = join(root, "console", "dist");
const out = join(root, "src", "dashboard", "assets.generated.ts");

const TYPES: Record<string, string> = {
  ".js": "text/javascript; charset=UTF-8",
  ".css": "text/css; charset=UTF-8",
  ".svg": "image/svg+xml",
  ".json": "application/json",
};

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}

const index = readFileSync(join(dist, "index.html"), "utf8");
const assets: Record<string, { type: string; body: string }> = {};
for (const file of walk(join(dist, "assets")).sort()) {
  const type = TYPES[extname(file)];
  if (type === undefined)
    throw new Error(`unexpected asset type: ${relative(dist, file)} (only text assets are embedded)`);
  assets[relative(join(dist, "assets"), file).split("\\").join("/")] = { type, body: readFileSync(file, "utf8") };
}

const lines = [
  "// Generated by scripts/embed-console.ts from console/ (`bun run console:build`). Do not edit.",
  "",
  `export const CONSOLE_INDEX_HTML: string = ${JSON.stringify(index)};`,
  "",
  "export const CONSOLE_ASSETS: Readonly<Record<string, { readonly type: string; readonly body: string }>> = {",
  ...Object.entries(assets).map(
    ([name, a]) => `  ${JSON.stringify(name)}: { type: ${JSON.stringify(a.type)}, body: ${JSON.stringify(a.body)} },`,
  ),
  "};",
  "",
];
writeFileSync(out, lines.join("\n"));
console.log(`embedded ${Object.keys(assets).length} assets + index.html → ${relative(root, out)}`);
